// Comprehensive health check
const { execSync } = require('child_process');
const checks = [];

try {
  const n8nHealth = execSync('curl -sf ' + $env.N8N_BASE_URL + '/healthz', { encoding: 'utf8', timeout: 5000 });
  checks.push({ name: 'n8n', status: 'healthy', detail: n8nHealth });
} catch (e) {
  checks.push({ name: 'n8n', status: 'unhealthy', detail: e.message });
}

try {
  const agentVersion = execSync('npx openclaw-code-agent@5.1.0 --version', { encoding: 'utf8', timeout: 10000 });
  checks.push({ name: 'code-agent', status: 'healthy', detail: agentVersion.trim() });
} catch (e) {
  checks.push({ name: 'code-agent', status: 'unhealthy', detail: e.message });
}

try {
  const tailscaleStatus = execSync('tailscale status --json', { encoding: 'utf8', timeout: 5000 });
  checks.push({ name: 'tailscale', status: 'healthy', detail: tailscaleStatus });
} catch (e) {
  checks.push({ name: 'tailscale', status: 'unhealthy', detail: e.message });
}

const allHealthy = checks.every(c => c.status === 'healthy');
return [{ json: { healthy: allHealthy, checks, timestamp: new Date().toISOString() } }];

// Trigger alerts for unhealthy components
const unhealthy = $json.checks.filter(c => c.status !== 'healthy');
return [{ json: { status: 'degraded', alerts: unhealthy } }];
